<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';use App\Services\AsaasHttpClient;
$base=(string)getenv('ASAAS_BASE_URL');$result=['ambiente_sandbox'=>str_contains(strtolower($base),'sandbox'),'api_key_configurada'=>(string)getenv('ASAAS_API_KEY')!=='','conta_acessivel'=>false,'pessoa_juridica'=>'nao_verificado','situacao'=>'nao_verificado','criacao_subcontas'=>'nao_verificado'];if(!$result['ambiente_sandbox']||!$result['api_key_configurada']){echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;exit(1);}try{$r=(new AsaasHttpClient())->verificarContaRaiz();$result['conta_acessivel']=true;$result['pessoa_juridica']=isset($r['personType'])?($r['personType']==='JURIDICA'): 'nao_verificado';$result['situacao']=$r['status']??'nao_verificado';}catch(Throwable){$result['situacao']='nao_verificado';}echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
